const size_t n = internal_key.size();
if (n < 8) return false;

const uint64_t num = DecodeFixed64(internal_key.data() + n - 8);
uint8_t t = static_cast<uint8_t>(num & 0xff);
if (t > kValueTypeForSeek) return false;

*user_key = Slice(internal_key.data(), n - 8);
*sequence = num >> 8;
*type = t;
return true;

